injected_css:
/* typography: L1.1.1, L1.1.2, L1.1.3 */
html, body { font-family: Verdana, Tahoma, Arial, Calibri, sans-serif !important; font-size: 18px !important; }
body * { font-family: inherit !important; }
p, li, dd, dt, td, th, blockquote, label, span, a, div { font-size: 1em !important; }
h1 { font-size: 1.8em !important; }
h2 { font-size: 1.5em !important; }
h3 { font-size: 1.3em !important; }
h4 { font-size: 1.2em !important; }
h5 { font-size: 1.2em !important; }
h6 { font-size: 1.2em !important; }

/* spacing: L1.1.4, L1.1.5, L1.1.6 */
html, body {
  line-height: 1.6 !important;
  letter-spacing: 0.175em !important;
  word-spacing: 0.612em !important;
}
body * { line-height: inherit !important; }

/* color: L1.2.1, L1.2.2 */
html, body { background: #FAF3E0 !important; color: #3A3A3A !important; }
body * { background-color: transparent !important; color: inherit !important; }
a { color: #1F4E79 !important; }

/* layout: L1.3.1, L1.3.2 */
body * { column-count: 1 !important; columns: auto !important; }
p, li, dd, blockquote { max-width: 65ch !important; }

/* emphasis: L1.1.7 */
body * { font-style: normal !important; text-decoration: none !important; }
b, strong, th, a { font-weight: 700 !important; }
